// Merkt sich, was der Simulator braucht (alles über MQTT, retained):
//   .../static/stations    Stationsliste (Lage, Kapazität)
//   .../profiles/+/+       Routen -> Start- und Zielstation
//   .../live/bicimad/+     echte Werte als Ausgangspunkt der Simulation
// Eigene simulierte Nachrichten (sim: ...) werden ignoriert.
const t = msg.topic || '';
const p = msg.payload;
const empty = p === '' || p == null || (Buffer.isBuffer(p) && p.length === 0);
if (t.endsWith('/static/stations')) {
    const map = {};
    (Array.isArray(p) ? p : []).forEach(s => { map[s.id] = s; });
    flow.set('stations', map);
} else if (t.indexOf('/profiles/') >= 0) {
    const key = t.split('/').slice(-2).join('/');
    const routes = flow.get('routes') || {};
    if (empty || typeof p !== 'object') delete routes[key];
    else routes[key] = { from: p.from.id, to: p.to.id };
    flow.set('routes', routes);
} else if (t.indexOf('/live/bicimad/') >= 0) {
    if (empty || typeof p !== 'object' || p.sim || p.demo) return null;
    const real = flow.get('realBikes') || {};
    real[t.split('/').pop()] = { bikes: p.bikes, docks: p.docks };
    flow.set('realBikes', real);
}
const n = Object.keys(flow.get('stations') || {}).length;
node.status({ fill: n ? 'green' : 'yellow', shape: 'dot',
    text: n + ' Stationen, ' + Object.keys(flow.get('routes') || {}).length + ' Routen bekannt' });
return null;

// ============================================================
//  Simulator für die Vorführung: ein fester Demo-Ablauf (ca. 3 min).
//  Eigener Dienst mit eigener Broker-Verbindung (g6-sim). Er veröffentlicht auf
//  DENSELBEN Topics wie der Python-Collector (.../live/bicimad/<id>, .../live/weather).
//  Empfehlungsdienst und Dashboard merken keinen Unterschied: Entkopplung über MQTT.
//
//  Steuerung: .../sim/cmd {scenario: 'demo' | 'stop'}
//  Zustand:   .../sim/state (retained) -> der Collector pausiert solange seine Live-Werte.
//  Simuliert werden Start- und Zielstationen aller Routen und ihre 4 nächsten Nachbarn.
//
//  Ablauf:   0 s  alles gut
//           20 s  Startstationen fast leer (1 Rad), Nachbarn haben Räder -> nur Hinweis
//           60 s  Vorhersage: Regen während der Fahrt -> Warnung
//          120 s  Regen vorbei, Lieferwagen bringt Räder -> Entwarnung
//          160 s  Ende (Werte bleiben, bis "Simulation beenden")
// ============================================================
const cfg = global.get('cfg');
const P = cfg.prefix;
let sim = context.get('sim') || { active: false };
const out = [];

const PHASES = [[0, '1/4 alles gut'], [20, '2/4 Startstationen fast leer, Ausweichstation in der Nähe'],
    [60, '3/4 Regen in der Vorhersage'], [120, '4/4 Regen vorbei, Räder aufgefüllt'], [160, 'Ende']];
const startTarget = t => t < 20 ? null : t < 120 ? 1 : 10;            // Räder an den Startstationen
const rainForecast = t => t >= 60 && t < 120;                          // Regen in der Vorhersage?

// Zufall mit festem Startwert: jeder Lauf sieht gleich aus
function rnd() {
    let a = (sim.seed = (sim.seed + 0x6D2B79F5) | 0);
    a = Math.imul(a ^ (a >>> 15), a | 1);
    a ^= a + Math.imul(a ^ (a >>> 7), a | 61);
    return ((a ^ (a >>> 14)) >>> 0) / 4294967296;
}
const dist = (a, b) => Math.hypot((a.lon - b.lon) * 85000, (a.lat - b.lat) * 111000);
const state = () => ({ topic: P + '/sim/state', qos: 1, retain: true,
    payload: { active: sim.active, label: sim.active ? 'Demo-Ablauf' : null, phase: sim.phase || null,
        startedAt: sim.startedAt || null } });

// ---------- Kommando ----------
const isCmd = msg.topic && msg.topic.endsWith('/sim/cmd');
if (isCmd) {
    const sc = msg.payload && msg.payload.scenario;
    if (sc === 'stop') {
        if (!sim.active) return null;
        sim = { active: false };
        context.set('sim', sim);
        node.status({ fill: 'grey', shape: 'ring', text: 'gestoppt' });
        // Der Collector soll sofort wieder echte Werte senden
        return [[state(),
            { topic: P + '/cmd/bicimad/refresh', payload: 'refresh', qos: 1, retain: false },
            { topic: P + '/cmd/weather/refresh', payload: 'refresh', qos: 1, retain: false }]];
    }
    if (sc !== 'demo') { node.warn('Unbekanntes Szenario: ' + sc); return null; }
    sim = { active: true, startedAt: Date.now(), seed: 20261120, st: {}, phase: null, lastFull: 0 };
}

// Nach einem Neustart einmal den Zustand melden (ein alter retained "aktiv" würde den
// Collector sonst dauerhaft pausieren) und jede Minute "online" bestätigen (Heartbeat).
if (!context.get('announced')) { context.set('announced', true); if (!sim.active) out.push(state()); }
if (Date.now() - (context.get('beat') || 0) > 60000) {
    context.set('beat', Date.now());
    out.push({ topic: P + '/system/sim', payload: 'online', qos: 1, retain: true });
}
if (!sim.active) { context.set('sim', sim); return out.length ? [out] : null; }

// ---------- Schritt (alle 5 s) ----------
const t = (Date.now() - sim.startedAt) / 1000;
const stations = flow.get('stations') || {};
const routes = flow.get('routes') || {};
const real = flow.get('realBikes') || {};
const list = Object.values(stations);
const ids = {}, starts = {};
for (const r of Object.values(routes)) {
    for (const id of [r.from, r.to]) {
        const s = stations[id];
        if (!s) continue;
        ids[id] = true;
        list.map(o => ({ id: o.id, d: dist(s, o) })).sort((a, b) => a.d - b.d).slice(1, 5).forEach(o => { ids[o.id] = true; });
    }
    starts[r.from] = true;
}
const full = Date.now() - sim.lastFull > 60000;     // jede Minute alles neu (frische Zeitstempel)
if (full) sim.lastFull = Date.now();
const target = startTarget(t);
for (const id of Object.keys(ids)) {
    const cap = stations[id].capacity || 20;
    let s = sim.st[id];
    if (!s) {
        const b = real[id] ? real[id].bikes : Math.round(cap * (0.35 + 0.3 * rnd()));
        s = sim.st[id] = { bikes: Math.max(starts[id] ? 6 : 4, b), sent: false };
    }
    const before = s.bikes;
    if (starts[id] && target !== null) s.bikes += Math.max(-3, Math.min(3, target - s.bikes));
    else if (rnd() < 0.3) s.bikes = Math.max(starts[id] ? 6 : 4, s.bikes + (rnd() < 0.5 ? -1 : 1));  // normaler Betrieb
    s.bikes = Math.max(0, Math.min(cap, s.bikes));
    if (s.bikes !== before || !s.sent || full) {
        s.sent = true;
        out.push({ topic: P + '/live/bicimad/' + id, qos: 0, retain: true,
            payload: { bikes: s.bikes, docks: cap - s.bikes, renting: true, returning: true, ts: Date.now(), demo: true } });
    }
}

// Wetter: aktuell trocken; in Phase 3 Regen in der Vorhersage (ab der nächsten Viertelstunde)
const rain = rainForecast(t);
if (rain !== sim.rain || full || isCmd) {
    sim.rain = rain;
    const q = 15 * 60000, t0 = Math.floor(Date.now() / q) * q;
    const forecast = [];
    for (let i = 0; i < 16; i++) {
        forecast.push({ t: t0 + i * q, temp: 15, wind: 10, precip: rain && i >= 1 ? 0.6 : 0 });
    }
    out.push({ topic: P + '/live/weather', qos: 0, retain: true,
        payload: { temp: 15, precip: 0, wind: 10, code: rain ? 3 : 1, ts: Date.now(), forecast: forecast,
            source: 'simulation', demo: true } });
}

const ph = PHASES.filter(p => p[0] <= t).pop()[1];
if (ph !== sim.phase) { sim.phase = ph; out.push(state()); }
context.set('sim', sim);
node.status({ fill: 'blue', shape: 'dot', text: ph + ' (' + Math.round(t) + ' s, ' + Object.keys(ids).length + ' Stationen)' });
return out.length ? [out] : null;
